#!/bin/sh
# The interface position, same question as `q2-replay.sh`: the pool-spelled
# `implements DI$Inner<String>` and the source-spelled `DI.Inner<String>` must compile to the
# same bytes, and the erased bridge must be regenerated by javac from the parameterized header.
# The self-named cell (`Self$Name implements java.lang.Comparable<Self$Name>`) is the `BR$Impl`
# shape: the type argument is a `$`-containing name of a class that is a top-level unit in this
# presentation's own convention (`class_name` keeps `$`; the raw header spells every parent that
# way already), and javac must rebuild the erased bridge from that header.
set -eu

J8=/Library/Java/JavaVirtualMachines/corretto-1.8.0_432/Contents/Home
WORK=/tmp/pih-iface-position
rm -rf "$WORK"
mkdir -p "$WORK/base8" "$WORK/base23" "$WORK/pool8" "$WORK/source8" "$WORK/pool23" "$WORK/source23" "$WORK/self8" "$WORK/self23"

cat >"$WORK/DI.java" <<'EOF'
public interface DI {
    interface Inner<T> {
        void put(T value);
    }
}
EOF
"$J8/bin/javac" -d "$WORK/base8" "$WORK/DI.java"
javac --release 8 -Xlint:-options -d "$WORK/base23" "$WORK/DI.java"

for dir in pool8 pool23; do
    cat >"$WORK/$dir/ImplI.java" <<'EOF'
public class ImplI implements DI$Inner<String> {
    public void put(String value) { }
    public static void main(String[] a) { System.out.println("iface"); }
}
EOF
done
for dir in source8 source23; do
    cat >"$WORK/$dir/ImplI.java" <<'EOF'
public class ImplI implements DI.Inner<String> {
    public void put(String value) { }
    public static void main(String[] a) { System.out.println("iface"); }
}
EOF
done

"$J8/bin/javac" -classpath "$WORK/base8" -d "$WORK/pool8" "$WORK/pool8/ImplI.java"
echo "pool   ImplI javac8 exit=0"
"$J8/bin/javac" -classpath "$WORK/base8" -d "$WORK/source8" "$WORK/source8/ImplI.java"
echo "source ImplI javac8 exit=0"
javac --release 8 -Xlint:-options -classpath "$WORK/base23" -d "$WORK/pool23" "$WORK/pool23/ImplI.java"
echo "pool   ImplI javac23 exit=0"
javac --release 8 -Xlint:-options -classpath "$WORK/base23" -d "$WORK/source23" "$WORK/source23/ImplI.java"
echo "source ImplI javac23 exit=0"
cmp "$WORK/pool8/ImplI.class" "$WORK/source8/ImplI.class"
echo "javac8  ImplI: IDENTICAL"
cmp "$WORK/pool23/ImplI.class" "$WORK/source23/ImplI.class"
echo "javac23 ImplI: IDENTICAL"

cat >"$WORK/Self\$Name.java" <<'EOF'
public class Self$Name implements java.lang.Comparable<Self$Name> {
    public int compareTo(Self$Name other) { return 0; }
    public static void main(String[] a) { System.out.println("self"); }
}
EOF
"$J8/bin/javac" -d "$WORK/self8" "$WORK/Self\$Name.java"
echo "pool self-name javac8 exit=0"
javac --release 8 -Xlint:-options -d "$WORK/self23" "$WORK/Self\$Name.java"
echo "pool self-name javac23 exit=0"
cmp "$WORK/self8/Self\$Name.class" "$WORK/self23/Self\$Name.class" >/dev/null 2>&1 || true
"$J8/bin/javap" -p -v -classpath "$WORK/self8" 'Self$Name' >"$WORK/self8/self-javap.txt"
grep -E "^public class|Signature:|ACC_BRIDGE|compareTo" "$WORK/self8/self-javap.txt"
"$J8/bin/javap" -p -v -classpath "$WORK/pool8" ImplI >"$WORK/pool8/impli-javap.txt"
echo "== the bridge javac regenerates from the parameterized pool-spelled header =="
grep -E "^public class|Signature:|ACC_BRIDGE" -A1 "$WORK/pool8/impli-javap.txt" | head -12
echo "IFACE POSITION OK"
